@Composable fun NotificationsScreen(nav:NavHostController,vm:NotificationsViewModel= viewModel()){val items by vm.notifications.collectAsState();Scaffold(containerColor=Canvas){pad->Column(Modifier.padding(pad).fillMaxSize().padding(20.dp)){Row(verticalAlignment=Alignment.CenterVertically){IconButton(onClick={nav.popBackStack()}){Icon(Icons.Rounded.ArrowBack,null)};PageTitle("Notificaciones")};Spacer(Modifier.height(10.dp));Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){FilterChip(true,{}, {Text("Todas")});FilterChip(false,{}, {Text("Tareas")});FilterChip(false,{}, {Text("Recordatorios")})};Spacer(Modifier.height(12.dp));items.forEach{n->Surface(Modifier.fillMaxWidth().padding(bottom=9.dp),shape=RoundedCornerShape(18.dp),color=Color.White){Row(Modifier.padding(14.dp),verticalAlignment=Alignment.CenterVertically){Box(Modifier.size(42.dp).clip(RoundedCornerShape(14.dp)).background(Lavender),contentAlignment=Alignment.Center){Icon(if(n.kind=="check")Icons.Rounded.CheckCircle else Icons.Rounded.NotificationsActive,null,tint=if(n.kind=="check")Lime else Violet)};Spacer(Modifier.width(12.dp));Column{Text(n.title,fontWeight=FontWeight.ExtraBold);Text(n.message,fontSize=12.sp,color=Muted);Text(n.whenText,fontSize=11.sp,color=Muted)}}}}}}}

